// `(cooldownID, ignoreCD)` of one item (`None` when it has no row).
pub fn item_cooldown(item_id: &str) -> Option<(&'static str, bool)> {
    ITEM_COOLDOWNS
        .iter()
        .find(|(id, _, _)| *id == item_id)
        .map(|(_, cooldown, ignore)| (*cooldown, *ignore))
}

